        sse_encode_String(mint, serializer);
      case WalletError_InvalidMint(mint: final mint):
        sse_encode_i_32(11, serializer);
        sse_encode_String(mint, serializer);
      case WalletError_InvalidTokenProgram(
        mint: final mint,
        tokenProgram: final tokenProgram,
      ):
        sse_encode_i_32(12, serializer);
        sse_encode_String(mint, serializer);
        sse_encode_String(tokenProgram, serializer);
      case WalletError_InvalidPubkey(value: final value):
        sse_encode_i_32(13, serializer);
        sse_encode_String(value, serializer);
      case WalletError_InvalidDerivationSignature():
        sse_encode_i_32(14, serializer);
      case WalletError_InvalidWalletKeys():
        sse_encode_i_32(15, serializer);
      case WalletError_TransportFailed(message: final message):
        sse_encode_i_32(16, serializer);
        sse_encode_String(message, serializer);
      case WalletError_SignatureInvalid():
        sse_encode_i_32(17, serializer);
      case WalletError_SignatureCountMismatch(
        expected: final expected,
        got: final got,
      ):
        sse_encode_i_32(18, serializer);
        sse_encode_u_64(expected, serializer);
        sse_encode_u_64(got, serializer);
      case WalletError_TransactionNotConfirmed(signature: final signature):
        sse_encode_i_32(19, serializer);
        sse_encode_String(signature, serializer);
      case WalletError_RemoteProverMissing():
        sse_encode_i_32(20, serializer);
      case WalletError_ProofMalformed():
        sse_encode_i_32(21, serializer);
      case WalletError_ProofInvalid():
        sse_encode_i_32(22, serializer);
      case WalletError_ProofFailed():
        sse_encode_i_32(23, serializer);
      case WalletError_ProverBusy():
        sse_encode_i_32(24, serializer);
      case WalletError_ProverClosed():
        sse_encode_i_32(25, serializer);
      case WalletError_ProverUnavailable():
        sse_encode_i_32(26, serializer);
      case WalletError_ProverInitFailed():
        sse_encode_i_32(27, serializer);
      case WalletError_ProverLoadFailed():
        sse_encode_i_32(28, serializer);
      case WalletError_UnsupportedCircuit():
        sse_encode_i_32(29, serializer);
      case WalletError_RpcUrlInsecure(url: final url):
        sse_encode_i_32(30, serializer);
        sse_encode_String(url, serializer);
      case WalletError_IndexerUrlInsecure(url: final url):
        sse_encode_i_32(31, serializer);
        sse_encode_String(url, serializer);
      case WalletError_ProvingKeyUrlInsecure(url: final url):
        sse_encode_i_32(32, serializer);
        sse_encode_String(url, serializer);
      case WalletError_ProverUrlInsecure(url: final url):
        sse_encode_i_32(33, serializer);
        sse_encode_String(url, serializer);
      case WalletError_ProvingKeyUnknown(name: final name):
        sse_encode_i_32(34, serializer);
        sse_encode_String(name, serializer);
      case WalletError_ProvingKeyMismatch(name: final name):
        sse_encode_i_32(35, serializer);
        sse_encode_String(name, serializer);
      case WalletError_ProvingKeyDownloadFailed(name: final name):
        sse_encode_i_32(36, serializer);
        sse_encode_String(name, serializer);
      case WalletError_ProvingKeyCorrupt(name: final name):
        sse_encode_i_32(37, serializer);
        sse_encode_String(name, serializer);
      case WalletError_ProvingKeyStoreFailed(path: final path):
        sse_encode_i_32(38, serializer);
        sse_encode_String(path, serializer);
      case WalletError_PoseidonInputCountInvalid(count: final count):
        sse_encode_i_32(39, serializer);
        sse_encode_u_64(count, serializer);
      case WalletError_PoseidonInputLengthInvalid(
        index: final index,
        length: final length,
      ):
        sse_encode_i_32(40, serializer);
        sse_encode_u_64(index, serializer);
        sse_encode_u_64(length, serializer);
      case WalletError_SignerMissing():
        sse_encode_i_32(41, serializer);
      case WalletError_SignerMismatch(
        wallet: final wallet,
        signer: final signer,
      ):
        sse_encode_i_32(42, serializer);
        sse_encode_String(wallet, serializer);
        sse_encode_String(signer, serializer);
      case WalletError_UnexpectedSigners(signers: final signers):
        sse_encode_i_32(43, serializer);
        sse_encode_list_String(signers, serializer);
      case WalletError_WalletClosed():
        sse_encode_i_32(44, serializer);
      case WalletError_Client(message: final message):
        sse_encode_i_32(45, serializer);
        sse_encode_String(message, serializer);
    }
  }

  @protected
  void sse_encode_wallet_keys(WalletKeys self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_prim_u_8_strict(self.viewingPrivateKey, serializer);
    sse_encode_list_prim_u_8_strict(self.viewingPublicKey, serializer);
    sse_encode_list_prim_u_8_strict(self.nullifierPrivateKey, serializer);
    sse_encode_list_prim_u_8_strict(self.nullifierPublicKey, serializer);
  }
}

@sealed
class MobileWalletImpl extends RustOpaque implements MobileWallet {
  // Not to be used by end users
  MobileWalletImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  MobileWalletImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_MobileWallet,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_MobileWallet,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_MobileWalletPtr,
  );

  /// Transaction history, read from the indexer now, newest first: one
  /// entry per asset each transaction moved, in SOL and every mint
  /// [`Self::balances`] reports.
  ///
  /// The indexer does not say which spends were withdrawals: a spend whose
  /// outputs are all this wallet's own is listed as a withdrawal, one with
  /// another wallet's output as sent.
  Future<List<ActivityEntry>> activity() =>
      RustLib.instance.api.zolanaMobileMobileWalletActivity(that: this);

  /// Spendable private balances, read from the indexer now: one per asset
  /// held in SOL and the configured mints.
  Future<List<TokenBalance>> balances() =>
      RustLib.instance.api.zolanaMobileMobileWalletBalances(that: this);

  /// Wait for a transaction the application sent itself: until Solana
  /// confirms it and, for shielded-pool transactions, the indexer has it,
  /// so the next balance or spend reads the notes it created and not the
  /// ones it spent.
  ///
  /// `signature` is the transaction signature, the fee payer's; it is
  /// checked against `pending` before anything is asked.
  Future<void> confirm({
    required PendingTransaction pending,
    required String signature,
  }) => RustLib.instance.api.zolanaMobileMobileWalletConfirm(
    that: this,
    pending: pending,
    signature: signature,
  );

  /// The keys [`Self::open_with_keys`] opens this wallet from.
  Future<WalletKeys> exportKeys() =>
      RustLib.instance.api.zolanaMobileMobileWalletExportKeys(that: this);

  /// Deposit public SOL (`mint` `None`) or tokens from this account into
  /// its own private balance. Deposits carry no proof.
  Future<PendingTransaction> prepareDeposit({
    String? mint,
    required BigInt amount,
  }) => RustLib.instance.api.zolanaMobileMobileWalletPrepareDeposit(
    that: this,
    mint: mint,
    amount: amount,
  );

  /// `None` when the registry already holds this wallet's address. Fails
  /// with [`WalletError::RegistrationConflict`] when it holds other keys:
  /// this wallet never replaces them.
  Future<PendingTransaction?> prepareRegistration() => RustLib.instance.api
      .zolanaMobileMobileWalletPrepareRegistration(that: this);

  /// Build and prove a private transfer to a registered wallet.
  ///
  /// Refuses an unregistered recipient instead of paying it publicly:
  /// [`Self::prepare_withdrawal`] makes a public payment explicit.
  ///
  /// `fee_payer` pays the network fee, this account when `None`. The proof
  /// binds it, so it cannot change after this call. Another fee payer signs
  /// first, before this account.
  ///
  /// `proving` says where it is proved, [`WalletConfig::proving`] when
  /// `None`. Remote proving without [`WalletConfig::prover_url`] fails with
  /// [`WalletError::RemoteProverMissing`]. The client verifies a remote
  /// proof against the pinned verifying key and the public input it computed
  /// itself before the message is built: a response that is not a proof of
  /// the pinned key fails with [`WalletError::ProofMalformed`], a proof that
  /// does not verify with [`WalletError::ProofInvalid`].
  Future<PendingTransaction> prepareTransfer({
    required String recipient,
    String? mint,
    required BigInt amount,
    String? feePayer,
    Proving? proving,
  }) => RustLib.instance.api.zolanaMobileMobileWalletPrepareTransfer(
    that: this,
    recipient: recipient,
    mint: mint,
    amount: amount,
    feePayer: feePayer,
    proving: proving,
  );

  /// Build and prove a withdrawal of private funds to the public account
  /// `recipient`. Tokens go to its associated token account. Without one
  /// the withdrawal could not settle, so it fails with
  /// `recipient_token_account_missing` before proving; the application
  /// creates the account with its own Solana client.
  ///
  /// `fee_payer` and `proving` work as in [`Self::prepare_transfer`].
  Future<PendingTransaction> prepareWithdrawal({
    required String recipient,
    String? mint,
    required BigInt amount,
    String? feePayer,
    Proving? proving,
  }) => RustLib.instance.api.zolanaMobileMobileWalletPrepareWithdrawal(
    that: this,
    recipient: recipient,
    mint: mint,
    amount: amount,
    feePayer: feePayer,
    proving: proving,
  );

  /// Spendable private balance of SOL (`mint` `None`) or `mint`, read from
  /// the indexer now.
  Future<BigInt> privateBalance({String? mint}) => RustLib.instance.api
      .zolanaMobileMobileWalletPrivateBalance(that: this, mint: mint);

  /// `pending` with a new blockhash and the same proof, for an approval that
  /// outlived [`PendingTransaction::last_valid_block_height`]. Signatures
  /// over the old message do not apply to the new one.
  ///
  /// The proof stays valid while the trees still hold the roots it was built
  /// on: a state tree keeps its last 500 roots, about its last 500
  /// transactions, and a nullifier tree its last 100 batch roots. After that
  /// the program rejects the proof as stale, and the spend is prepared again.
  ///
  /// A refreshed spend reserves its notes again until its new last valid
  /// block height.
  Future<PendingTransaction> refresh({required PendingTransaction pending}) =>
      RustLib.instance.api.zolanaMobileMobileWalletRefresh(
        that: this,
        pending: pending,
      );

  /// Whether the user registry publishes this wallet's shielded address.
  /// Others can only send to a registered wallet.
  Future<RegistrationStatus> registrationStatus() => RustLib.instance.api
      .zolanaMobileMobileWalletRegistrationStatus(that: this);

  /// Release the notes `pending` reserves, so the next spend can select
  /// them: for a prepared spend that will not be sent, such as one the user
  /// declined. Submitting or confirming it does this too.
  Future<void> release({required PendingTransaction pending}) => RustLib
      .instance
      .api
      .zolanaMobileMobileWalletRelease(that: this, pending: pending);

  Future<String> shieldedAddress() =>
      RustLib.instance.api.zolanaMobileMobileWalletShieldedAddress(that: this);

  /// Attach the signatures, send, and wait as [`Self::confirm`] does.
  /// Returns the signature.
  ///
  /// `signatures` follows [`PendingTransaction::signers`]; each is checked
  /// before anything is sent.
  Future<String> submit({
    required PendingTransaction pending,
    required List<Uint8List> signatures,
  }) => RustLib.instance.api.zolanaMobileMobileWalletSubmit(
    that: this,
    pending: pending,
    signatures: signatures,
  );

  /// Wait for a shielded-pool transaction by its signature alone, such as one
  /// sent before the application restarted: until Solana confirms it and the
  /// indexer has it, so the next balance reads its notes. A transaction that
  /// failed on chain fails here with the chain's error.
  Future<void> waitForTransaction({required String signature}) =>
      RustLib.instance.api.zolanaMobileMobileWalletWaitForTransaction(
        that: this,
        signature: signature,
      );
}

